package io.github.ningpp.compat;

/**
 * Mirrors the BCL {@code System.Collections.Generic.IAsyncEnumerable<T>}
 * interface for converted C# code (generated by CSharpToJava converter).
 *
 * <p>The BCL method has an optional {@code CancellationToken} parameter whose
 * default is {@code CancellationToken.None}; Java has no default arguments, so
 * the expanded C# produced by the async-normalize pass always passes the token
 * explicitly at the call site ({@code getAsyncEnumerator(CancellationToken.getNone())}
 * for a bare {@code await foreach}), and this bridge requires it likewise.
 * The C# {@code WithCancellation(token)} chain is resolved on the C# side
 * before conversion and has no mapping here (C38 design §5.2 item 4).</p>
 *
 * @param <T> type of the enumerated elements
 */
public interface AsyncEnumerable<T> {

    /**
     * Mirrors {@code IAsyncEnumerable<T>.GetAsyncEnumerator(CancellationToken = default)}.
     *
     * @param cancellationToken the cancellation token (never null at the
     *                          expanded call site; pass
     *                          {@link CancellationToken#getNone()} for the BCL default)
     * @return the async enumerator
     */
    AsyncEnumerator<T> getAsyncEnumerator(CancellationToken cancellationToken);
}
